def clean(x):
    if isinstance(x,dict):return {str(k):clean(v) for k,v in x.items()}
    if isinstance(x,(list,tuple,np.ndarray)):return [clean(v) for v in x]
    if isinstance(x,np.generic):x=x.item()
    if isinstance(x,float) and not np.isfinite(x):return None
    return x
def b64(path,mime):return 'data:'+mime+';base64,'+base64.b64encode(path.read_bytes()).decode()
def write_atomic(path,text):
    temporary=path.with_name('.'+uuid.uuid4().hex+'-'+path.name)
    temporary.write_text(text);temporary.replace(path)
def save_figure_atomic(fig,path,ext,dpi):
    temporary=path.with_name('.'+uuid.uuid4().hex+'-'+path.name)
