    fig,ax=plt.subplots(figsize=(24,max(5,len(ks)*.20+2.5)));ax.imshow(rgba,aspect='auto',interpolation='nearest');ax.set_yticks(range(len(ks)),[short[k]+' · '+k for k in ks],fontsize=7)
