    axes[0].set_ylim(-.5,len(picked)-.5);axes[0].invert_yaxis();fig.suptitle(info['name']+' · environmental sensitivity',fontsize=17);fig.subplots_adjust(left=.20,right=.98,top=.82,bottom=.24,wspace=.2)
    fig.text(.03,.10,'Point: study-adjusted positive-response slope. Line: range after omitting a study with environmental contrasts.',fontsize=9);fig.text(.03,.045,'These are exploratory diagnostics. Lines are NOT confidence intervals; no observed-gene p or q values are shown.',fontsize=9,color='#805f25')
