    D=clean(dict(world=world,reactions=ps,genes={k:short[k] for k in ks},full_names={k:inv.loc[k,'name'] for k in ks},first_gene=picked[0],groups=groups.to_dict('index'),samples=samples[[c for c in ['study_id','coordinate_group','analysis_group','lat','lon','Country','Locality','REALM','bio1','soc_mean','phh2o_mean','total_KO_assignments'] if c in samples]].to_dict('index'),group_values=gr[ks].to_dict('index'),sample_values=rel.loc[ks].T.to_dict('index'),coordinate_values=cg[ks].to_dict('index'),global_values=globals,palette=palette,vmax=vmax,heatmap_order=list(order),diagnostics=diags[diags.KO.isin(ks)].to_dict('records'),rule_samples={th:{s:{k:v for k,v in x.items() if k in ruleids} for s,x in tab.items()} for th,tab in rule_samples.items()},rule_groups={th:{s:{k:v for k,v in x.items() if k in ruleids} for s,x in tab.items()} for th,tab in rule_groups.items()},rule_global={th:{k:v for k,v in x.items() if k in ruleids} for th,x in rule_global.items()}))
